from solution import surfacearea_cube


def test_issue_example_five():
    """Example 'assert surfacearea_cube(5)==150'."""
    assert surfacearea_cube(5) == 150  # 6*5*5 = 6*25 = 150


def test_issue_unit_cube():
    """Rule 'surface area of a cube' is 6*l^2 for l=1."""
    assert surfacearea_cube(1) == 6  # 6*1*1 = 6*1 = 6


def test_issue_side_two():
    """Rule 'surface area of a cube' is 6*l^2 for l=2."""
    assert surfacearea_cube(2) == 24  # 6*2*2 = 6*4 = 24


def test_issue_side_four():
    """Rule 'surface area of a cube' is 6*l^2 for l=4."""
    assert surfacearea_cube(4) == 96  # 6*4*4 = 6*16 = 96


def test_issue_side_ten():
    """Rule 'surface area of a cube' is 6*l^2 for l=10."""
    assert surfacearea_cube(10) == 600  # 6*10*10 = 6*100 = 600


