def test_contract_large_side_hundred():
    """Contract 'surface area of a cube' must stay 6*l^2 for large l=100."""
    assert surfacearea_cube(100) == 60000  # 6*100*100 = 6*10000 = 60000


def test_contract_float_three():
    """Contract 'surface area of a cube' must stay 6*l^2 for float l=3.0."""
    assert surfacearea_cube(3.0) == 54.0  # 6*3*3 = 6*9 = 54
